/**
 * GENERATED by `scripts/inline-email-assets.ts` from `src/email/assets/`.
 * Do not edit; change the image and rerun the script.
 *
 * The images every email shows, as bytes rather than links.
 *
 * They used to be `<img src="https://langx.io/…">`, and were missing from
 * most inboxes: Outlook blocks remote images until somebody clicks "download
 * pictures", Apple Mail does the same with remote content off, and the app's
 * own file preview does too. Gmail showed them only because it fetches
 * through its own proxy. An inline attachment referenced as `cid:` is shown
 * by all of them without asking, because it arrived with the mail. `data:`
 * URIs would have been simpler and Gmail strips them.
 *
 * `ResendEmailSender` attaches whichever of these a message's HTML
 * references; templates and campaign bodies only have to use the `cid:` src.
 */
export interface InlineAsset {
  cid: string
  filename: string
  contentType: string
  base64: string
}

